parameters.jsCode:
// Contrato de entrada. Todo lo que quiera hablar con WhatsApp pasa por aquí.
//   accion      : texto | imagen | documento | audio | video | marcar_leido
//   cliente_id  : wa_id del destinatario (regla 3: nunca el teléfono formateado)
//   texto       : cuerpo, o pie de foto si es media
//   media_url   : URL pública del adjunto
//   nombre_fichero: nombre real, solo documentos (Meta lo enseña como título)
//   tamano      : bytes, para registrarlo en `adjuntos`
//   miniatura_url : primer fotograma del vídeo, hace de poster en el inbox
//   autor       : bot | humano | sistema   (queda registrado en mensajes)
//   responder_a : wamid al que se responde (opcional)
//   wa_message_id : solo para marcar_leido

const e = $json || {};
const accion = String(e.accion || 'texto').toLowerCase();
const ACCIONES = ['texto','imagen','documento','audio','video','marcar_leido'];

const fallos = [];
if (!ACCIONES.includes(accion)) fallos.push('accion no reconocida: ' + accion);
if (accion === 'marcar_leido') {
  if (!e.wa_message_id) fallos.push('marcar_leido necesita wa_message_id');
} else {
  if (!e.cliente_id) fallos.push('falta cliente_id');
  if (accion === 'texto' && !e.texto) fallos.push('un texto vacío no se envía');
  if (accion !== 'texto' && !e.media_url) fallos.push('falta media_url para ' + accion);
}
if (!$env.WA_TOKEN) fallos.push('falta WA_TOKEN en el entorno de n8n');

// Fallamos aquí, antes de gastar una llamada a Meta y antes de escribir nada.
if (fallos.length) {
  throw new Error('Petición inválida — ' + fallos.join(' · '));
}

return [{ json: {
  accion,
  cliente_id:    String(e.cliente_id || ''),
  texto:         e.texto || '',
  media_url:     e.media_url || null,
  autor:         ['bot','humano','sistema'].includes(e.autor) ? e.autor : 'bot',
  responder_a:   e.responder_a || null,
  wa_message_id: e.wa_message_id || null,
  // Indicador de "escribiendo": va en la MISMA llamada que marcar como leido.
  // Se descarta solo al responder o a los 25s. Solo se pide si vamos a responder.
  typing:        e.typing === true,
  nombre:        e.nombre || null,
  nombre_fichero: e.nombre_fichero || null,
  tamano:        Number(e.tamano) || null,
  miniatura_url: e.miniatura_url || null,
} }];

// Traduce el contrato interno al cuerpo que espera la Cloud API.
const p = $('Validar petición').first().json;

const cuerpo = {
  messaging_product: 'whatsapp',
  recipient_type: 'individual',
  to: p.cliente_id,
};

if (p.accion === 'texto') {
  cuerpo.type = 'text';
  cuerpo.text = { preview_url: false, body: p.texto };
} else {
  // La Cloud API tiene sus nombres y nosotros los nuestros. Sin este
  // mapa, 'documento' viajaba tal cual y Meta lo rechazaba entero.
  const TIPO_WA = { imagen: 'image', documento: 'document', audio: 'audio', video: 'video' };
  cuerpo.type = TIPO_WA[p.accion];
  if (!cuerpo.type) throw new Error('accion sin tipo de Cloud API: ' + p.accion);
  const adj = { link: p.media_url };
  // audio y video no admiten caption en la Cloud API; image y document sí.
  if (p.texto && ['image','document'].includes(cuerpo.type)) adj.caption = p.texto;
  // filename SOLO existe para document. Es lo que ve el cliente como
  // titulo; sin el, WhatsApp saca el nombre de la URL y le llega un
  // "1787391234-catalogo.pdf" con el sello de tiempo delante.
  if (cuerpo.type === 'document' && p.nombre_fichero) adj.filename = p.nombre_fichero;
  cuerpo[cuerpo.type] = adj;
}

// Responder en hilo, si nos lo han pedido.
if (p.responder_a) cuerpo.context = { message_id: p.responder_a };

return [{ json: { cuerpo, peticion: p } }];

// Se registra SIEMPRE, salga bien o mal (regla 1).
const p = $('Validar petición').first().json;
const r = $json || {};

const codigo = r.statusCode || 0;
const cuerpo = r.body || r;
// Doble negacion: sin ella, && devuelve el array messages en vez de true.
const ok = !!(codigo >= 200 && codigo < 300 && cuerpo && cuerpo.messages);

const wamid = ok ? (cuerpo.messages[0] || {}).id : null;
const error = ok ? null : ((cuerpo && cuerpo.error) || { message: r.error || 'sin respuesta de Meta' });

const TIPO = { texto: "text", imagen: "image", documento: "document", audio: "audio", video: "video" };

return [{ json: {
  ok,
  wamid,
  error,
  fila: {
    cliente_id:   p.cliente_id,
    canal:        'whatsapp_cloud',
    direccion:    'out',
    autor:        p.autor,
    tipo:         TIPO[p.accion] || 'text',
    texto:        p.texto || null,
    media_url:    p.media_url,
    estado:       ok ? 'enviado' : 'fallido',
    msg_id_canal: wamid,
    payload:      ok ? null : { error, enviado: $("Construir mensaje Cloud API").first().json.cuerpo },
  },
} }];

// Lo que ve quien nos llamó.
const r = $('Preparar fila saliente').first().json;
return [{ json: { ok: r.ok, wamid: r.wamid, error: r.error } }];

// Registra en `adjuntos` lo que sale, igual que se hace con lo que entra.
// Sin esto un PDF enviado desde el inbox solo dejaba `media_url`, y el
// hilo no podia enseñar ni el peso ni la miniatura del video.
const p = $('Validar petición').first().json;

// La respuesta del insert puede venir como array, como cadena, o ya
// partida en items por n8n. Las tres formas acaban igual.
let filas = $json;
if (filas && filas.body !== undefined) filas = filas.body;
if (typeof filas === 'string') { try { filas = JSON.parse(filas); } catch (e) {} }
if (!Array.isArray(filas)) filas = filas ? [filas] : [];
const fila = filas.find(f => f && f.id) || null;

const TIPO = { imagen: 'image', documento: 'document', audio: 'audio', video: 'video' };
const tipo = TIPO[p.accion];

// Sin media, sin tipo con hueco en `adjuntos`, o sin fila a la que
// colgarse, no hay nada que registrar. La fila puede faltar si el insert
// choco con un duplicado: `Registrar salida` va con ignore-duplicates.
if (!tipo || !p.media_url || !fila) {
  return [{ json: { saltar: 'si' } }];
}

return [{ json: {
  saltar: 'no',
  mensaje_id: fila.id,
  tipo,
  // Lo saliente vive en el bucket PUBLICO `media` porque Meta tiene que
  // poder descargarlo. Por eso aqui va la URL entera y no una ruta: el
  // inbox la reconoce como URL y la usa tal cual, sin firmarla.
  storage_path: p.media_url,
  tamano: p.tamano,
  miniatura: p.miniatura_url,
} }];

// POR QUE NUMERO SALE ESTE MENSAJE.
//
// Sale por el mismo por el que entro la conversacion, que es el unico
// que el cliente reconoce. Contestar desde otro numero es, para el
// cliente, un desconocido escribiendole.
//
// Si no se puede averiguar, se cae al de wa.env: es el comportamiento
// de siempre y con un solo numero acierta. Pero se marca, porque con
// varios numeros ese acierto es casualidad.
const r = $json || {};
let cuerpo = r.body;
if (typeof cuerpo === 'string') { try { cuerpo = JSON.parse(cuerpo); } catch (e) {} }
const fila = Array.isArray(cuerpo) && cuerpo.length ? cuerpo[0] : null;
const canal = fila && fila.canales ? (Array.isArray(fila.canales) ? fila.canales[0] : fila.canales) : null;

const phone_id = (canal && canal.identificador) || $env.WA_PHONE_NUMBER_ID;

return [{ json: {
  phone_id,
  canal_nombre: canal ? canal.nombre : '(por defecto de wa.env)',
  // Un canal desactivado NO envia. Desactivar significa exactamente eso:
  // las conversaciones se siguen viendo, pero por ahi no sale nada.
  canal_activo: canal ? canal.activo !== false : true,
  por_defecto: canal ? false : true,
} }];

// Mismo contrato que "Devolver resultado", para que quien llamo se
// entere del motivo en vez de recibir un silencio.
return [{ json: {
  ok: false,
  wamid: null,
  error: 'El canal de esta conversacion esta desactivado: no se puede enviar por el. Actívalo en el inbox → Canales.',
} }];
